/*
 * A072266  Number of words of length 2n generated by the two letters s and t
 *          that reduce to the identity 1 using the relations sssssss=1, tt=1
 *          and stst=1. The generators s and t along with the three relations
 *          generate the 14-element dihedral group D7.
 * https://oeis.org/A072266
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 5, u16 n <= 9, u32 n <= 17, u64 n <= 33, u128 n <= 65,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Recurrence: a(n)=9*a(n-1)-26*a(n-2)+25*a(n-3)-4*a(n-4) (n>4),    a(0)=1, a(1)=1, a(2)=3, a(3)=10, a(4)=35 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* static storage for computed values */
    static seq_t *seq = NULL;   /* array of a(0)..a(M) */
    static idx_t len   = 0;     /* number of valid entries in seq  */
    static idx_t cap   = 0;     /* allocated capacity of seq       */

    /* initialise first five terms on first call */
    if (seq == NULL)
    {
        cap = 16;              /* initial capacity larger than needed */
        seq = (seq_t *)malloc(sizeof(seq_t) * cap);
        seq[0] = 1;
        seq[1] = 1;
        seq[2] = 3;
        seq[3] = 10;
        seq[4] = 35;
        len   = 5;
    }

    /* enlarge storage if required */
    if (n >= cap)
    {
        idx_t new_cap = cap * 2;
        if (new_cap <= n) new_cap = n + 1;
        seq_t *tmp = (seq_t *)realloc(seq, sizeof(seq_t) * new_cap);
        if (tmp == NULL) return 0; /* allocation failed, return 0 */
        seq = tmp;
        cap = new_cap;
    }

    /* compute missing values up to n */
    if (n >= len)
    {
        for (idx_t i = len; i <= n; ++i)
        {
            seq_t t1 = seq[i - 1] * (seq_t)9;
            seq_t t2 = seq[i - 2] * (seq_t)26;
            seq_t t3 = seq[i - 3] * (seq_t)25;
            seq_t t4 = seq[i - 4] * (seq_t)4;
            seq[i] = t1 - t2 + t3 - t4;
        }
        len = n + 1;
    }

    return seq[n];
}
